#!/usr/bin/env node
/**
 * Portfolio OS — deterministic, non-destructive archive pages.
 * Source of truth: content/project-registry-2026-11.json.
 * Source links/claim scopes: database/evidence-reconciliation-2026-11.json.
 * CV references: content/cv-records-2026-11.json.
 * Generated files have the marker below and must never replace hand-authored pages.
 */
import fs from 'node:fs';
import path from 'node:path';
const ROOT=process.cwd();
const read=p=>JSON.parse(fs.readFileSync(path.join(ROOT,p),'utf8'));
const registry=read('content/project-registry-2026-11.json').projects;
const evidence=read('database/evidence-reconciliation-2026-11.json').projects;
const records=read('content/cv-records-2026-11.json').records;
const evidenceById=new Map(evidence.map(x=>[x.project_id,x]));
const media=read('database/media-publication-register-2026-11.json').assets;
const mediaById=new Map(media.map(x=>[x.project_id,x]));
const MARK='<!-- Generated by scripts/build-project-record-pages.mjs — edits belong in canonical data. -->';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const validUrl=u=>typeof u==='string'&&/^https:\/\/[^ "'<>]+$/.test(u);
const isPublicCover=p=>p?.image?.startsWith('/assets/') || /^https:\/\/virtura\.space\/VIRTURA_WEBSITE_ASSETS\//.test(p?.image||'');
const isDraft=x=>/待补|待核|待整理|待归档|筹备|来源待/i.test(x||'');
const css=':root{--bg:#f7f7f4;--fg:#242724;--muted:#68716c;--line:#d4d8d1}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--fg);font:14px/1.75 -apple-system,BlinkMacSystemFont,"Noto Sans CJK SC",Arial,sans-serif}a{color:inherit;text-underline-offset:4px}a:focus-visible{outline:2px solid #48747b;outline-offset:3px}.wrap{max-width:1050px;padding:0 30px;margin:auto}nav{display:flex;align-items:center;justify-content:space-between;gap:15px;flex-wrap:wrap;padding:20px 0;border-bottom:1px solid var(--line);font-size:12px}nav a{text-decoration:none}.eyebrow{font-size:11px;letter-spacing:.07em;color:var(--muted)}header{padding:60px 0 40px}h1{font:400 clamp(32px,5.4vw,60px)/1.12 Georgia,"Noto Serif CJK SC",serif;letter-spacing:-.04em;margin:12px 0}h1 small{display:block;font:400 .43em Georgia,serif;letter-spacing:0;color:#7d8580;margin-top:12px}.summary{font-size:16px;max-width:800px}.meta{display:flex;flex-wrap:wrap;gap:12px;color:var(--muted);font-size:12px;padding:14px 0;border-top:1px solid var(--line);border-bottom:1px solid var(--line)}.art{margin:28px 0 12px}.art img{display:block;max-width:100%;max-height:530px;width:auto;height:auto;object-fit:contain}.art figcaption{font-size:11px;color:var(--muted);margin-top:12px}.section{display:grid;grid-template-columns:150px minmax(0,1fr);gap:25px;padding:35px 0;border-bottom:1px solid var(--line)}.section h2{font-size:12px;font-weight:600;margin:0;text-transform:uppercase;letter-spacing:.06em}.section p{margin:0 0 13px}.entries{margin:0;padding:0;list-style:none}.entries li{padding:12px 0;border-bottom:1px solid var(--line)}.entries li:last-child{border:none}.rowmeta{display:block;color:var(--muted);font-size:11px}.links{display:flex;flex-wrap:wrap;gap:10px}.links a{display:inline-block;padding:9px 13px;border:1px solid #bdc5bd;text-decoration:none;font-size:12px}.links a:hover{background:#e7ebe6}footer{padding:27px 0 65px;font-size:11px;color:var(--muted)}@media(max-width:700px){.wrap{padding:0 18px}.section{display:block}.section h2{margin-bottom:14px}header{padding:43px 0 28px}.summary{font-size:14px}}';
const outputDir=path.join(ROOT,'works/projects');fs.mkdirSync(outputDir,{recursive:true});
const ids=new Set(),writes=[];
for(const p of registry){
 if(!/^[a-z0-9][a-z0-9-]*$/.test(p.id))throw Error('Bad project id '+p.id);
 if(ids.has(p.id))throw Error('Duplicate project id '+p.id);
 ids.add(p.id);
 const ev=evidenceById.get(p.id);
 const summary=!isDraft(p.note)?p.note:'本档案保存项目的名称、关联呈现及公开出处。媒体与详细说明以对应作品资料为准。';
 const authors=Array.isArray(p.authors)?p.authors.join(' / '):'';
 const mediaInfo=mediaById.get(p.id);
 const caption=mediaInfo?.caption_zh?'<figcaption>'+esc(mediaInfo.caption_zh)+'</figcaption>':'';
 const cover=isPublicCover(p)?'<figure class="art"><img src="'+esc(p.image)+'" alt="'+esc(p.zh)+'" loading="lazy">'+caption+'</figure>':'';
 const workUrl=validUrl(p.url)&&!p.url.includes('/works/projects/'+p.id+'.html')?p.url:null;
 const direct=workUrl?'<a href="'+esc(workUrl)+'">完整作品或合作案例 / View work</a>':'';
 const sourceEntries=(ev?.sources||[]).filter(s=>validUrl(s.url)).slice(0,12);
 const cv=records.filter(r=>r.project_id===p.id||r.related_work_ids?.includes(p.id));
 const variants=Array.isArray(p.variants)?p.variants:[];
 const urls=sourceEntries.length?'<ul class="entries">'+sourceEntries.map(s=>'<li><a href="'+esc(s.url)+'" target="_blank" rel="noopener">'+esc(new URL(s.url).hostname)+'</a><span class="rowmeta">公开来源 / '+esc(s.kind||'reference')+'</span></li>').join('')+'</ul>':'<p>本条目暂未附独立公开来源；公开署名以现有项目记录为准。</p>';
 const relatedCV=cv.length?'<ul class="entries">'+cv.map(r=>'<li><a href="../records/'+esc(r.id)+'.html">'+esc(r.zh)+'</a><span class="rowmeta">'+esc(r.year)+' · '+esc(r.section)+'</span></li>').join('')+'</ul>':'<p>没有单独绑定到此项目的履历事件；查看完整 CV 索引。</p>';
 const variantsHTML=variants.length?'<ul class="entries">'+variants.map(v=>'<li>'+esc(v.title||v.legacy_id)+'<span class="rowmeta">'+esc(v.year||'')+' · 历史关联版本，具体关系以原始资料为准</span></li>').join('')+'</ul>':'<p>暂无另外登记的版本。</p>';
 const html='<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+esc(p.zh)+' / '+esc(p.en)+' — Ewan Qian Archive</title><meta name="description" content="'+esc(summary.slice(0,165))+'"><meta name="archive-project-id" content="'+esc(p.id)+'"><link rel="canonical" href="https://ewanqian.site/works/projects/'+esc(p.id)+'.html"><style>'+css+'</style></head><body>'+MARK+'<div class="wrap"><nav><a href="../../">EWAN QIAN / 钱誉文</a><span><a href="../cv.html">CV</a>　<a href="../archive-2026.html">PROJECT ARCHIVE</a></span></nav><header><div class="eyebrow">PERMANENT PROJECT RECORD · '+esc(p.id)+'</div><h1>'+esc(p.zh)+'<small>'+esc(p.en)+'</small></h1><p class="summary">'+esc(summary)+'</p><div class="meta"><span>'+esc(p.year)+'</span><span>'+esc(p.category||'Archive')+'</span>'+(authors?'<span>Authors / '+esc(authors)+'</span>':'')+'</div>'+cover+'<div class="links">'+direct+'<a href="../archive-2026.html#'+esc(p.id)+'">项目索引 / Archive index</a><a href="../cv-records.html">履历记录 / CV records</a></div></header><main><section class="section"><h2>Presentations / 关联呈现</h2><div>'+variantsHTML+'</div></section><section class="section"><h2>CV / 履历</h2><div>'+relatedCV+'</div></section><section class="section"><h2>Sources / 公开来源</h2><div><p class="eyebrow">来源网址仅支持其原文具体陈述，不自动证明每项个人职责或奖项等级。</p>'+urls+'</div></section></main><footer>Portfolio OS · 本项目身份固定，媒体与展示可持续更新。 <a href="../archive-2026.html">返回项目存档</a></footer></div></body></html>\n';
 const file=path.join(outputDir,p.id+'.html');
 if(fs.existsSync(file)&&!fs.readFileSync(file,'utf8').includes(MARK))throw Error('Refusing to overwrite hand-authored file: '+file);
 const old=fs.existsSync(file)?fs.readFileSync(file,'utf8'):null;
 if(old!==html){fs.writeFileSync(file,html);writes.push(p.id)}
}
const report={schema:'portfolio-generated-project-pages.v1',registered:registry.length,changed:writes.length,changed_ids:writes};
console.log(JSON.stringify(report));
